let imageItem=document.querySelectorAll(".image-item"),images=document.querySelectorAll(".image-item img"),lightbox=document.getElementById("lightbox"),lightboxImg=document.getElementById("lightbox-img"),zoomSlider=document.getElementById("zoom-slider"),lightboxContainer=document.querySelector(".lightbox-container"),imageNum=document.querySelector(".actual-img-num"),totalImageNum=document.querySelector(".total-img-num"),currentIndex=0,scale=1;images.forEach((e,t)=>{e.addEventListener("click",()=>{openLightbox(t),imageItem.forEach(e=>{e.style.display="none"})})});function openLightbox(e){currentIndex=e,lightbox.style.display="flex",lightboxImg.src=images[currentIndex].src,lightboxContainer.scrollTop=0,imageNum.innerHTML=currentIndex+1,totalImageNum.innerHTML=images.length}function prevImage(){currentIndex=(currentIndex-1+images.length)%images.length,lightboxImg.src=images[currentIndex].src,lightboxContainer.scrollTop=0,imageNum.innerHTML=currentIndex+1}function nextImage(){currentIndex=(currentIndex+1)%images.length,lightboxImg.src=images[currentIndex].src,lightboxContainer.scrollTop=0,imageNum.innerHTML=currentIndex+1}document.addEventListener("keydown",e=>{lightbox.style.display=="flex"&&(e.key==="ArrowLeft"?prevImage():e.key==="ArrowRight"?nextImage():e.key==="Escape"&&closeLightbox())});function scrollToBottom(){window.scrollTo({top:document.body.scrollHeight,behavior:"smooth"})}function updateScrollButton(){lightbox.style.display==="flex"?document.body.classList.add("lightbox-active"):document.body.classList.remove("lightbox-active")}images.forEach((e,t)=>{e.addEventListener("click",()=>{openLightbox(t),updateScrollButton()})});function closeLightbox(){lightboxImg.style.transform="scale(1)",zoomSlider.value=1,lightbox.style.display="none",imageItem.forEach(e=>e.style.display="block"),updateScrollButton()}zoomSlider.addEventListener("input",()=>{scale=zoomSlider.value,lightboxImg.style.transform=`scale(${scale})`,scale>1?lightboxContainer.style.overflow="auto":lightboxContainer.style.overflow="hidden",simulateCloseOpen()}),document.addEventListener("wheel",e=>{isNegOrPos=e.deltaY,lightbox.style.display==="flex"&&(isNegOrPos<0?scale=scale+.1:scale=scale-.1,scale=Math.max(1,Math.min(scale,2)),zoomSlider.value=scale,lightboxImg.style.transform=`scale(${scale})`,scale>1?lightboxContainer.style.overflow="auto":lightboxContainer.style.overflow="hidden",simulateCloseOpen())});function simulateCloseOpen(){lightboxContainer.style.display="none",setTimeout(()=>{lightboxContainer.style.display="flex"},1)}